use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::snapshot::LayoutSnapshot;
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_s_artifact_layout_layout_mutations_decisions::target::*;

struct Keys(Vec<String>);
impl LayoutTargetSource for Keys{fn identity(&self)->usize{17}fn count(&self)->usize{self.0.len()}fn key(&self,index:usize)->&str{&self.0[index]}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close(lookup:&mut LayoutTargetLookup){lookup.begin_close();assert_eq!(lookup.close_step(Default::default()).progress(),Default::default());lookup.close_step(grant(lookup.close_demand()));assert!(lookup.terminal_is_empty())}
#[test]
fn neutral_semantic_targets_resolve_under_exact_original_grants(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let source=Keys(row["keys"].as_array().unwrap().iter().map(|s|s.as_str().unwrap().to_owned()).collect());let target=row["target"].as_str().unwrap();let mut lookup=LayoutTargetLookup::new();for _ in 0..100000{let demand=lookup.demand();for axis in 0..3{let mut short=grant(demand);match axis{0=>short.maximum_items=0,1=>short.maximum_copy_bytes-=1,_=>short.maximum_depth=0}assert_eq!(lookup.advance(&source,19,target,short).unwrap().progress(),Default::default())}let step=lookup.advance(&source,19,target,grant(demand)).unwrap();assert!(step.progress().fits(grant(demand)));if matches!(step,RetainedCloneStep::Complete(_)){break}}assert_eq!(lookup.result(),Some(row["index"].as_u64().map(|i|i as usize)));close(&mut lookup);for cut in[0,1,7,33]{let mut partial=LayoutTargetLookup::new();for _ in 0..cut{let d=partial.demand();if matches!(partial.advance(&source,19,target,grant(d)).unwrap(),RetainedCloneStep::Complete(_)){break}}close(&mut partial)}}}
#[test]
fn long_unicode_target_reads_only_funded_chunks(){let prefix="世界🌍".repeat(10000);let source=Keys(vec![format!("{prefix}a"),format!("{prefix}b")]);let target=format!("{prefix}b");let mut lookup=LayoutTargetLookup::new();let mut turns=0;loop{let d=lookup.demand();let step=lookup.advance(&source,19,&target,grant(d)).unwrap();turns+=1;assert!(step.progress().fits(grant(d)));if matches!(step,RetainedCloneStep::Complete(_)){break}assert!(turns<100000)}assert!(turns>700);assert_eq!(lookup.result(),Some(Some(1)));close(&mut lookup)}
